// === Tab: Stages ===
const easings = [easeOutBounce, easeOutBounce, easeOutQuart];

function initStages() {
	let stages = [];

	stages[0] = initCircle();
	stages[1] = initSquare();
	stages[2] = initSquare(HALF_PI);
	stages[3] = initCircle(HALF_PI);

	return stages;
}

function initCircle(alphaOffset = 0) {
	let points = [];
	for(let i = 0; i < numPoints; i++) {
		let alpha = (i / numPoints) * TWO_PI;
		let x = sin(alpha + alphaOffset) * meanRad;
		let y = cos(alpha + alphaOffset) * meanRad;
		points.push(createVector(x, y))
	}
	return points;
}

function initSquare(alphaOffset = 0) {
	let points = [];
	for(let i = 0; i < numPoints; i++) {
		let alpha = (i / numPoints) * TWO_PI;

		let x = sin(alpha + alphaOffset);
		let y = cos(alpha + alphaOffset);

		if (abs(x) < abs(y)) {
			x = x / abs(y);
			y = y / abs(y);
		} else {
			y = y / abs(x);
			x = x / abs(x);
		}

		points.push(createVector(x * meanRad * 1.5, y * meanRad * 1.5))
	}
	return points;
}

function initStar(alphaOffset = 0) {
	let points = [];
	for(let i = 0; i < numPoints; i++) {
		let alpha = (i / numPoints) * TWO_PI;
		let offset = sin(alphaOffset + alpha * 1/PI) * meanRad * 1;
		let x = sin(alpha + alphaOffset) * (meanRad + offset);
		let y = cos(alpha + alphaOffset) * (meanRad + offset);
		points.push(createVector(x, y))
	}
	return points;
}

function noEase(x) {
	return x
}

function easeOutBounce(x) {
	const n1 = 7.5625;
	const d1 = 2.75;

	if (x < 1 / d1) {
			return n1 * x * x;
	} else if (x < 2 / d1) {
			return n1 * (x -= 1.5 / d1) * x + 0.75;
	} else if (x < 2.5 / d1) {
			return n1 * (x -= 2.25 / d1) * x + 0.9375;
	} else {
			return n1 * (x -= 2.625 / d1) * x + 0.984375;
	}
}

function easeOutQuart(x) {
	return 1 - pow(1 - x, 4);
}

